const _managerNames = ['김선생','이선생','박선생','최선생','정선생','강선생','조선생','윤선생','임선생','한선생'];

function _gen(schools) {
  const groups = [];
  let id = 1;
  schools.forEach((s, si) => {
    const grades = s.type === '초등학교' ? 6 : 3;
    for (let g = 1; g <= grades; g++) {
      for (let c = 1; c <= 5; c++) {
        const seed = si * 100 + g * 10 + c;
        const sc = 30 + seed % 11;
        groups.push({
          groupId: `g${id++}`,
          name: `${g}학년 ${c}반`,
          studentCount: sc,
          deviceCount: sc - (2 + seed % 5),
          policyCount: seed % 4,
          pauseStatus: seed % 23 === 0 ? 'paused' : 'normal',
          status: 'active',
          updatedAt: `2026-03-${String(1 + seed % 16).padStart(2, '0')}`,
          schoolId: s.schoolId,
          manager: _managerNames[seed % _managerNames.length],
        });
      }
    }
  });
  return groups;
}

